import{_ as A,o as e,c as l,a0 as o}from"./chunks/framework.DqMqoJl9.js";const r="data:image/png;base64,",n="data:image/png;base64,",t="/assets/clickHijack_20201103201937.D-al1qmQ.png",d=JSON.parse('{"title":"点击劫持","description":"","frontmatter":{},"headers":[],"relativePath":"loophole/clickHijack.md","filePath":"loophole/clickHijack.md","lastUpdated":1791573371000}'),s={name:"loophole/clickHijack.md"};function p(i,a,c,m,E,f){return e(),l("div",null,[...a[0]||(a[0]=[o('<h1 id="点击劫持" tabindex="-1">点击劫持 <a class="header-anchor" href="#点击劫持" aria-label="Permalink to &quot;点击劫持&quot;">​</a></h1><h2 id="_1-攻击原理" tabindex="-1">1 攻击原理 <a class="header-anchor" href="#_1-攻击原理" aria-label="Permalink to &quot;1 攻击原理&quot;">​</a></h2><ul><li>用户在登陆 A 网站的系统后，被攻击者诱惑打开第三方网站</li><li>而第三方网站通过 iframe 引入了 A 网站的页面内容</li><li>用户在第三方网站中点击某个按钮（被装饰的按钮），实际上是点击了 A 网站的按钮</li></ul><p>特征：</p><ul><li>用户亲手操作</li><li>用户不知情 (看不到真实的页面，被诱导点击)</li></ul><h2 id="_2-场景" tabindex="-1">2 场景 <a class="header-anchor" href="#_2-场景" aria-label="Permalink to &quot;2 场景&quot;">​</a></h2><p>如图是一个平平无奇的按钮，页面中看不到其他内容：</p><p><img src="'+r+'" alt=""></p><p>但实际上这个按钮被一个 iframe 给覆盖了，这个 iframe 的透明度为 0</p><p>点击按钮时，实际上点击的是 iframe 内的按钮</p><p><img src="'+n+`" alt=""></p><p>实际情况中可能会用更丰富的引导做一些危险的操作，比如破坏、盗取数据，付款转账等。</p><h2 id="_3-点击劫持防御" tabindex="-1">3 点击劫持防御 <a class="header-anchor" href="#_3-点击劫持防御" aria-label="Permalink to &quot;3 点击劫持防御&quot;">​</a></h2><p>点击劫持攻击的前提是网页能够通过 iframe 嵌套到其他网站，那么防止网页被嵌套到其他网站就能一定程度的防御点击劫持</p><h3 id="_3-1-javascript-禁止内嵌" tabindex="-1">3.1 javascript 禁止内嵌 <a class="header-anchor" href="#_3-1-javascript-禁止内嵌" aria-label="Permalink to &quot;3.1 javascript 禁止内嵌&quot;">​</a></h3><p>有一个全局对象 <code>window.top</code>，返回窗口层级最顶层窗口的引用</p><p>如果当前页面没有被嵌套，那么 <code>window.top === window</code></p><p>可以通过 <code>top.lcation === window.location</code> 来判断页面是否被嵌套</p><p>如果被嵌套，可以更改 <code>top.location.href</code> 将父级页面跳走</p><blockquote><p>注意：受同源策略影响，如果嵌套的页面和父页面不同域，那么无法获取 top 对象下面的值。但是可以用在判断语句中，并且允许修改部分值，比如 <code>top.location.href</code></p></blockquote><p>但是这个方案有一个缺陷，iframe 可以阻止 script 运行</p><div class="language-html line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6A737D;">&lt;!-- 不允许运行脚本，只允许提交表单 --&gt;</span></span>
<span class="line"><span style="color:#24292E;">&lt;</span><span style="color:#22863A;">iframe</span><span style="color:#6F42C1;"> src</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;http:xxx.com&quot;</span><span style="color:#6F42C1;"> sandbox</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;allow-forms&quot;</span><span style="color:#24292E;">&gt;&lt;/</span><span style="color:#22863A;">iframe</span><span style="color:#24292E;">&gt;</span></span>
<span class="line"><span style="color:#6A737D;">&lt;!-- sandbox allow-forms: 允许嵌入的浏览上下文提交表单。如果没有使用该关键字，则无法提交表单 --&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><a href="https://developer.mozilla.org/zh-CN/docs/Web/HTML/Element/iframe" target="_blank" rel="noreferrer">sandbox 其他值见文档</a></p><h3 id="_3-2-x-frame-options" tabindex="-1">3.2 X-Frame-Options <a class="header-anchor" href="#_3-2-x-frame-options" aria-label="Permalink to &quot;3.2 X-Frame-Options&quot;">​</a></h3><p><a href="https://developer.mozilla.org/zh-CN/docs/Web/HTTP/X-Frame-Options" target="_blank" rel="noreferrer">X-Frame-Options 文档</a></p><p>The X-Frame-Options HTTP 响应头是用来给浏览器 指示允许一个页面 可否在 <code>&lt;frame&gt;</code>, <code>&lt;iframe&gt;</code>, <code>&lt;embed&gt;</code> 或者 <code>&lt;object&gt;</code> 中展现的标记。站点可以通过确保网站没有被嵌入到别人的站点里面，从而避免 clickjacking 攻击</p><p>这个响应头需要在服务端设置</p><p>兼容性 (2020-11-03 数据)</p><p><img src="`+t+'" alt=""></p>',29)])])}const R=A(s,[["render",p]]);export{d as __pageData,R as default};
